package jp.tapmarker;
public class StaleCompletionTest {
 public static void main(String[] args){PhaseEngine e=new PhaseEngine();e.strictRuntime=true;PhaseEngine.Phase a=new PhaseEngine.Phase(),b=new PhaseEngine.Phase();a.id="a";b.id="b";e.phases.put(a.id,a);e.phases.put(b.id,b);PhaseEngine.Watch w=new PhaseEngine.Watch();w.id="go";w.nextPhase="b";a.watches.add(w);e.enter("a",0);long original=e.epoch;e.enter("b",1);if(e.finishIfCurrent(w,"a",original,2)||!e.current.equals("b"))throw new AssertionError("stale different state");e.enter("a",3);if(e.finishIfCurrent(w,"a",original,4))throw new AssertionError("same name new generation");long latest=e.epoch;a.watches.remove(w);if(e.finishIfCurrent(w,"a",latest,5))throw new AssertionError("removed arrow");a.watches.add(w);if(!e.finishIfCurrent(w,"a",latest,6)||!e.current.equals("b"))throw new AssertionError("current completion");if(e.finishIfCurrent(w,"a",latest,7))throw new AssertionError("duplicate completion");System.out.println("PASS 5 stale/removed/duplicate completion checks");}
}
